cat > /tmp/orient.mjs <<'EOF'
// Brute-force Life step on a sparse set, to check which y-orientation
// makes the spec's ASCII before/after grids actually consistent.
const step = (cells) => {
  const key = ([x,y]) => `${x},${y}`;
  const live = new Set(cells.map(key));
  const counts = new Map();
  for (const [x,y] of cells)
    for (let dx=-1; dx<=1; dx++)
      for (let dy=-1; dy<=1; dy++) {
        if (!dx && !dy) continue;
        const k = key([x+dx, y+dy]);
        counts.set(k, (counts.get(k) ?? 0) + 1);
      }
  const out = [];
  for (const [k,n] of counts)
    if (n === 3 || (n === 2 && live.has(k))) out.push(k.split(',').map(Number));
  return out.sort((a,b)=>a[0]-b[0] || a[1]-b[1]);
};

// Parse an ASCII block. rows are given top-to-bottom.
// mode 'down': y increases downward (row index == y)
// mode 'up'  : y increases upward  (y == lastRow - rowIndex)
const parse = (rows, mode) => {
  const out = [];
  rows.forEach((row, r) => {
    [...row].forEach((ch, x) => {
      if (ch === '#') out.push([x, mode === 'down' ? r : (rows.length-1-r)]);
    });
  });
  return out.sort((a,b)=>a[0]-b[0] || a[1]-b[1]);
};

const show = (cs) => JSON.stringify(cs);
const cases = {
  'rule2 survival': [['###','...','.#.'], ['.#.','.#.','...']],
  'rule3 overpop':  [['###','.#.','###'], ['#.#','#.#','#.#']],
  'rule4 reprod':   [['##.','#..','...'], ['##.','##.','...']],
};
for (const mode of ['down','up']) {
  console.log(`\n=== y increases ${mode.toUpperCase()} ===`);
  for (const [name,[before,after]] of Object.entries(cases)) {
    const got = step(parse(before, mode));
    const want = parse(after, mode);
    console.log(`${show(got)===show(want)?'MATCH  ':'differ '} ${name}`);
    if (show(got)!==show(want)) console.log(`    got ${show(got)}\n   want ${show(want)}`);
  }
}
// Blinker, as given with explicit coords in the spec
console.log('\n=== blinker (explicit coords, orientation-free) ===');
console.log('gen0 -> ', show(step([[0,0],[0,1],[0,2]])), ' want [[-1,1],[0,1],[1,1]]');
console.log('gen1 -> ', show(step([[-1,1],[0,1],[1,1]])), ' want [[0,0],[0,1],[0,2]]');
console.log('block -> ', show(step([[0,0],[1,0],[0,1],[1,1]])));
console.log('pair  -> ', show(step([[0,1],[1,1]])));
console.log('single-> ', show(step([[0,0]])));
EOF
node /tmp/orient.mjs

