cat > src/game-of-life.spec.ts <<'EOF'
import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

// Coordinate convention: cells are [x, y]. The spec's only examples that give
// explicit coordinates (blinker, block) are consistent with either vertical
// orientation, so the axis sign is left free; tests below use the spec's own
// coordinate lists wherever it supplies them.
describe("Game of Life - nextGeneration", () => {
  it.todo("should return [] for an empty grid — [] -> []");

  it.todo("should kill a lone cell (underpopulation, 0 neighbors) — [(0,0)] -> []");

  it.todo("should kill both cells of a horizontal pair (underpopulation, 1 neighbor each) — [(0,1), (1,1)] -> []");

  it.todo("should keep a live cell with exactly 2 neighbors alive (survival)");

  it.todo("should keep a live cell with exactly 3 neighbors alive (survival)");

  it.todo("should kill a live cell with more than 3 neighbors (overpopulation) — centre of \"###\"/\".#.\"/\"###\" dies");

  it.todo("should birth a dead cell with exactly 3 neighbors (reproduction) — \"##.\"/\"#..\"/\"...\" births (1,1)");

  it.todo("should leave a dead cell with fewer than 3 neighbors dead (no reproduction)");

  it.todo("should keep the block still life unchanged — [(0,0), (1,0), (0,1), (1,1)] -> unchanged");

  it.todo("should oscillate the blinker gen 0 -> gen 1 — [(0,0), (0,1), (0,2)] -> [(-1,1), (0,1), (1,1)]");

  it.todo("should oscillate the blinker gen 1 -> gen 2 — [(-1,1), (0,1), (1,1)] -> [(0,0), (0,1), (0,2)]");

  it.todo("should handle a pattern entirely in negative space — block at [(-3,-3), (-2,-3), (-3,-2), (-2,-2)] -> unchanged");

  it.todo("should not return duplicate cells");
});
EOF
